style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* ========== YOUR BACKGROUND IMAGE ========== */
  html::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    background-image: url("https://i.imgur.com/a0nEjdn.png"); /* ← put your image link here */
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    background-attachment: fixed;
    opacity: 0.85; /* lower = more transparent / darker look */
    pointer-events: none;
  }

  /* Remove default Roblox backgrounds */
  html,
  body,
  .rbx-body,
  #container,
  #MasterContainer,
  .container-main,
  .content,
  .section-content,
  .rbx-left-col,
  .left-col-list,
  .profile-container,
  .profile-header,
  .profile-header-content,
  .game-details-page,
  .game-details-play-button-container {
    background: transparent !important;
    background-image: none !important;
    background-color: transparent !important;
  }

  /* Make header / top bar semi-transparent (glass look) */
  .rbx-header,
  .dark-theme .rbx-header,
  .light-theme .rbx-header {
    background-color: rgba(0, 0, 0, 0.35) !important;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;
  }

  /* Side navigation / left column */
  .rbx-left-col,
  .dark-theme .rbx-left-col {
    background-color: rgba(0, 0, 0, 0.25) !important;
    backdrop-filter: blur(10px);
  }

  /* Main content cards & sections */
  .section-content,
  .game-card-container,
  .item-card-container,
  .thumbnail-2d-container,
  .profile-about,
  .profile-stats-container,
  .modal-content,
  .dropdown-menu,
  .popover,
  .chat-main,
  .chat-container {
    background-color: rgba(20, 20, 25, 0.45) !important;
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.06) !important;
  }

  /* Keep text readable */
  body,
  .dark-theme,
  .light-theme {
    color: #f0f0f5 !important;
  }

  /* Optional: softer scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.25);
    border-radius: 4px;
  }
}
